"""Whole-request validation for the certified sharing-replay protocol."""
from __future__ import annotations
import json


class InvalidRequest(ValueError):
    pass


def bad():
    raise InvalidRequest('invalid_request')


def loads(raw):
    """Parse exactly one UTF-8 JSON value, rejecting duplicate object keys.

    Python's JSON decoder already rejects trailing non-whitespace data,
    malformed UTF-8, malformed escapes, NaN/Infinity and non-JSON tokens.
    The object_pairs_hook is installed at every object depth and therefore
    also rejects duplicate keys everywhere.
    """
    def pairs(items):
        d = {}
        for k, v in items:
            if k in d:
                bad()
            d[k] = v
        return d

    def constant(_):
        bad()

    try:
        if isinstance(raw, (bytes, bytearray)):
            text = raw.decode('utf-8')
        elif isinstance(raw, str):
            text = raw
        else:
            bad()
        return json.loads(text, object_pairs_hook=pairs, parse_constant=constant)
    except InvalidRequest:
        raise
    except (ValueError, UnicodeError, RecursionError, OverflowError):
        bad()


def keys(x, names):
    if type(x) is not dict or set(x) != set(names.split()):
        bad()


def integer(x, lo, hi):
    # bool is a subclass of int; the exact type check excludes it.
    if type(x) is not int or not lo <= x <= hi:
        bad()


def sequence(x, lo, hi):
    if type(x) is not list or not lo <= len(x) <= hi:
        bad()


def path_ok(path, source, sink, edges):
    if path is None:
        return
    sequence(path, 1, 12)
    current = source
    seen = {source}
    for e in path:
        integer(e, 0, len(edges) - 1)
        u, v, _ = edges[e]
        if u != current or v in seen:
            bad()
        seen.add(v)
        current = v
    if current != sink:
        bad()


def distinct(paths):
    values = []
    for p in paths:
        if p is not None:
            values.append(tuple(p))
    if len(values) != len(set(values)):
        bad()


def mode(x):
    if type(x) is not str or x not in ('route', 'admit'):
        bad()


def validate(v):
    """Validate the complete request without mutating it.

    Path-slot transaction state is maintained in a private copy, so configure
    transactions after restores are validated against exactly the slot state
    that replay will see.
    """
    keys(v, 'cases')
    sequence(v['cases'], 0, 6)
    events_total = 0
    issues_total = 0

    for case in v['cases']:
        keys(case, 'nodes edges commodities workers quorum max_lag relax rho mode events')
        n = case['nodes']
        integer(n, 2, 32)

        edges = case['edges']
        sequence(edges, 1, 64)
        pairs = set()
        for edge in edges:
            sequence(edge, 3, 3)
            u, w, cap = edge
            integer(u, 0, n - 1)
            integer(w, 0, n - 1)
            integer(cap, 0, 1000)
            if u == w or (u, w) in pairs:
                bad()
            pairs.add((u, w))

        coms = case['commodities']
        sequence(coms, 0, 24)
        slots = []
        slot_total = 0
        for com in coms:
            keys(com, 'source sink demand paths')
            s, t = com['source'], com['sink']
            integer(s, 0, n - 1)
            integer(t, 0, n - 1)
            if s == t:
                bad()
            integer(com['demand'], 0, 1000)
            sequence(com['paths'], 0, 8)
            slot_total += len(com['paths'])
            for p in com['paths']:
                path_ok(p, s, t, edges)
            distinct(com['paths'])
            slots.append(list(com['paths']))
        if slot_total > 96:
            bad()

        workers = case['workers']
        sequence(workers, 1, 8)
        ownership = []
        for ids in workers:
            sequence(ids, 0, len(coms))
            for k in ids:
                integer(k, 0, len(coms) - 1)
            if ids != sorted(set(ids)):
                bad()
            ownership.extend(ids)
        if sorted(ownership) != list(range(len(coms))):
            bad()

        integer(case['quorum'], 1, len(workers))
        integer(case['max_lag'], 0, 12)
        sequence(case['relax'], 2, 2)
        a, b = case['relax']
        integer(a, 1, 16)
        integer(b, 1, 16)
        if not b <= a < 2 * b:
            bad()
        integer(case['rho'], 1, 8)
        mode(case['mode'])
        sequence(case['events'], 1, 256)

        tickets = set()
        saves = {}
        for ev in case['events']:
            events_total += 1
            if events_total > 384:
                bad()
            if type(ev) is not dict or type(ev.get('op')) is not str:
                bad()
            op = ev['op']

            if op == 'configure':
                keys(ev, 'op mode capacity demand paths')
                mode(ev['mode'])
                for field, size in (('capacity', len(edges)), ('demand', len(coms))):
                    sequence(ev[field], 0, size)
                    used = set()
                    for pair in ev[field]:
                        sequence(pair, 2, 2)
                        idx, value = pair
                        integer(idx, 0, size - 1)
                        integer(value, 0, 1000)
                        if idx in used:
                            bad()
                        used.add(idx)
                sequence(ev['paths'], 0, 96)
                used = set()
                next_slots = [list(group) for group in slots]
                for change in ev['paths']:
                    sequence(change, 3, 3)
                    k, p, path = change
                    integer(k, 0, len(coms) - 1)
                    integer(p, 0, len(slots[k]) - 1)
                    if (k, p) in used:
                        bad()
                    used.add((k, p))
                    path_ok(path, coms[k]['source'], coms[k]['sink'], edges)
                    next_slots[k][p] = path
                # Distinctness is checked after the atomic transaction.
                for group in next_slots:
                    distinct(group)
                slots = next_slots

            elif op == 'issue':
                keys(ev, 'op id worker')
                integer(ev['id'], 0, 10 ** 9)
                integer(ev['worker'], 0, len(workers) - 1)
                if ev['id'] in tickets:
                    bad()
                tickets.add(ev['id'])
                issues_total += 1
                if issues_total > 48:
                    bad()

            elif op == 'deliver':
                keys(ev, 'op id')
                integer(ev['id'], 0, 10 ** 9)
                if ev['id'] not in tickets:
                    bad()

            elif op == 'retune':
                keys(ev, 'op rho')
                integer(ev['rho'], 1, 8)

            elif op == 'save':
                keys(ev, 'op name')
                integer(ev['name'], 0, 10 ** 9)
                if ev['name'] in saves:
                    bad()
                saves[ev['name']] = [list(group) for group in slots]

            elif op == 'restore':
                keys(ev, 'op name')
                integer(ev['name'], 0, 10 ** 9)
                if ev['name'] not in saves:
                    bad()
                slots = [list(group) for group in saves[ev['name']]]

            elif op in ('step', 'audit'):
                keys(ev, 'op')

            else:
                bad()

    return v
